func (sblock serverBlock) listenerAddrsForServerBlockKey(key string,
	options map[string]interface{}) ([]string, error) {
	addr, err := ParseAddress(key)
	if err != nil {
		return nil, fmt.Errorf("parsing key: %v", err)
	}
	addr = addr.Normalize()
	for _, parsed := range sblock.keys {
		if parsed.Original == key || parsed.Original == addr.Original {
			addr = parsed
			break
		}
	}

	// figure out the HTTP and HTTPS ports; either
	// use defaults, or override with user config
	httpPort, httpsPort := strconv.Itoa(caddyhttp.DefaultHTTPPort), strconv.Itoa(caddyhttp.DefaultHTTPSPort)
	if hport, ok := options["http_port"]; ok {
		httpPort = strconv.Itoa(hport.(int))
	}
	if hsport, ok := options["https_port"]; ok {
		httpsPort = strconv.Itoa(hsport.(int))
	}

	// Listener port follows the site address components.
	lnPort := httpsPort
	explicitPort := addr.Port
	siteScheme := addr.Scheme
	siteHost := addr.Host
	sitePath := addr.Path
	siteOriginal := addr.Original
	if explicitPort != "" {
		lnPort = explicitPort
	} else if siteScheme == "http" {
		lnPort = httpPort
	} else if siteScheme == "https" || siteHost != "" || sitePath != "" || siteOriginal != "" {
		lnPort = httpsPort
	}

	// error if scheme and port combination violate convention
	if (addr.Scheme == "http" && lnPort == httpsPort) || (addr.Scheme == "https" && lnPort == httpPort) {
		return nil, fmt.Errorf("[%s] scheme and port violate convention", key)
	}

	// the bind directive specifies hosts, but is optional
	lnHosts := make([]string, 0, len(sblock.pile))
	for _, cfgVal := range sblock.pile["bind"] {
		lnHosts = append(lnHosts, cfgVal.Value.([]string)...)
	}
	if len(lnHosts) == 0 {
		if defaultBind, ok := options["default_bind"].(string); ok {
			lnHosts = []string{defaultBind}
		} else {
			lnHosts = []string{""}
		}
	}

	// use a map to prevent duplication
	listeners := make(map[string]struct{}, len(sblock.keys))
	for _, host := range lnHosts {
		addr, err := caddy.ParseNetworkAddress(host)
		if err == nil && addr.IsUnixNetwork() {
			listeners[host] = struct{}{}
		} else {
			listeners[host+":"+lnPort] = struct{}{}
		}
	}

	// now turn map into list
	listenersList := make([]string, 0, len(listeners))
	for lnStr := range listeners {
		listenersList = append(listenersList, lnStr)
	}

	return listenersList, nil
}

